\begin{proposition}
All six dial cells lie in the deployment band $[0.60,0.85]$, and in each cell the dial exceeds the bare count by at least $0.11$.
\end{proposition}

\begin{proposition}[Exact mean advantages]
With $\overline{T}_{\beta},\overline{Q}_{\beta}$ the seed means at bit length $\beta$: $\overline{T}_{48}-\overline{Q}_{48}=\frac{3}{25}=0.12$ and $\overline{T}_{52}-\overline{Q}_{52}=\frac{7}{50}=0.14$, both exact rational identities.
\end{proposition}

\begin{proposition}[Measured drift]
$\overline{T}_{48}-\overline{T}_{52}=\frac{9}{2500}=0.0036$, i.e.\ $0.0009$ per bit, with $\overline{T}_{48}=0.719733\ldots$ and $\overline{T}_{52}=0.716133\ldots$
\end{proposition}

\begin{theorem}[The observed bit-length effect is not geometric]\label{thm:noise}
For every depth $1\le t\le 47$ and each of the three ceilings,
\[
\bigl|\Ceil_{\bullet}(47,t)-\Ceil_{\bullet}(51,t)\bigr|\cdot 10^{37}\;<\;\overline{T}_{48}-\overline{T}_{52}.
\]
\end{theorem}

\begin{proof}
By Theorem~\ref{thm:4852} the left side is at most $10^{-3}$, while the right side is $3.6\times 10^{-3}$.
\end{proof}

The residual $0.0036$ is therefore attributable to sampling; this is corroborated by the within-row scatter, which already reaches $0.0015$ at a fixed bit length.

\section{Structural separation from the bare count}\label{sec:sep}

The measured relation rate is $p=1/8$, i.e.\ depth $t=3$.

\begin{theorem}[Uniform bare-count cap]\label{thm:cap}
For every $b\ge 6$, $\;\Ceil_{\mathrm{coarse}}(b,3)<0.3829$.
\end{theorem}

\begin{proof}
The bitlen-free value is $g_{\mathrm{coarse}}(3)=\frac{7}{2}\cdot\frac18\cdot\frac78=\frac{49}{128}=0.3828125$, and by Corollary~\ref{cor:close} the ceiling is at most $\frac{49}{128}+3\cdot 8^{-b}\le \frac{49}{128}+3/262144<0.38283$.
\end{proof}

The hypothesis $b\ge 6$ is essentially sharp: at $b=4$ the coarse ceiling is $0.3829059\ldots$, just above the stated cap.

\begin{lemma}\label{lem:above}
For $b\ge1$, $t\ge1$, $\;\Ceil_{\mathrm{coarse}}(b,t)>g_{\mathrm{coarse}}(t)$: the finite-size ceiling always exceeds its bitlen-free value, since the Möbius factor is $>1$.
\end{lemma}

\begin{theorem}[Bitlen-uniform separation]\label{thm:sep}
For every $b\ge 6$, all six recorded dial cells satisfy $\rho^{2}>\Ceil_{\mathrm{coarse}}(b,3)$ and all six recorded bare-count cells satisfy $\rho^{2}<\Ceil_{\mathrm{coarse}}(b,3)$.
\end{theorem}

\begin{proof}
Every dial cell has $\rho^{2}\ge 0.7154^{2}=0.511797>0.3829$, which dominates the ceiling by Theorem~\ref{thm:cap}; every bare-count cell has $\rho^{2}\le 0.6005^{2}=0.360600<\frac{49}{128}$, which is dominated by the ceiling via Lemma~\ref{lem:above}.
\end{proof}

Hence the advantage is not a calibration accident at one bit length: the coarse ceiling separates the two response classes uniformly in $b$. Any response reporting only a bare count at relation rate $1/8$ is capped at $\rho<0.6188$.

\section{Neither cliff nor decline}\label{sec:nocliff}

\begin{theorem}[The whole band is admissible at every bit length]\label{thm:band}
For every $v\in[0.60,0.85]$ and every $b\ge 1$, $\;v^{2}<\CC(A_{b})$. Equivalently, $0.85<\sqrt{\CC(A_{b})}$ for all $b\ge 1$.
\end{theorem}

\begin{proof}
$v^{2}\le 0.7225<\frac{6}{7}<\CC(A_{b})$ by Theorem~\ref{thm:dyadic}.
\end{proof}

A bit-length-induced collapse cannot originate in the tie structure; it would have to come from the arithmetic being sampled, not from the instrument.

Now take the measured drop entirely at face value and extrapolate linearly with slope $-0.0009$ per bit:
\[
D(\beta)\;=\;\overline{T}_{48}+\frac{\overline{T}_{52}-\overline{T}_{48}}{4}\,(\beta-48).
\]

\begin{theorem}[Worst-case decline stays in band]\label{thm:decline}
For every $48\le\beta\le 160$, $\;0.60\le D(\beta)\le 0.85$.
\end{theorem}

\begin{proof}
$D$ is decreasing, $D(48)=0.719733\ldots\le 0.85$ and $D(160)=0.618933\ldots\ge 0.60$.
\end{proof}

Selected values: $D(64)=0.705333$, $D(96)=0.676533$, $D(128)=0.647733$, $D(160)=0.618933$. Moreover every bit-length-$52$ cell retains a margin of at least $0.11$ above the band floor, so no cliff occurs across the measured step.

\begin{theorem}[Payload: bitlen-stability of the dial]
All of the following hold simultaneously: (i) all six recorded cells lie in $[0.60,0.85]$; (ii) in each cell the dial beats the bare count by at least $0.11$; (iii) the mean advantages are exactly $+0.12$ and $+0.14$; (iv) for every depth $1\le t\le 47$ the ceilings at the two bit lengths differ by at most $10^{-40}$; (v) every band value $v$ satisfies $v^{2}<\CC(A_{b})$ at every bit length $b\ge 1$.
\end{theorem}

Items (i)--(iii) are the measurement; (iv)--(v) say that the tie geometry can produce neither a graceful decline nor a cliff.

\section{The modulus axis: a live parameter and a refuted conjecture}\label{sec:modulus}

\begin{definition}
For $\ell\ge 2$ let $A_{b}^{(\ell)}=\bigl((\ell-1)\ell^{\,b-1},(\ell-1)\ell^{\,b-2},\dots,(\ell-1),1\bigr)$, with $\sum A_{b}^{(\ell)}=\ell^{b}$. For $\ell=2$ this is $A_{b}$.
\end{definition}

\begin{theorem}[Arithmetic bridge]\label{thm:bridge}
For $\ell\ge 2$ and $k<b$, exactly $(\ell-1)\ell^{\,b-1-k}$ of the integers in $\{0,\dots,\ell^{b}-1\}$ have $\ell$-adic valuation exactly $k$; together with $\{0\}$ these classes exhaust the sample.
\end{theorem}

\begin{proof}[Proof sketch]
The set of $x<\ell^{b}$ with $\ell^{k}\mid x$, $\ell^{k+1}\nmid x$ is the injective image of $\{0,\dots,\ell^{\,b-1-k}-1\}\times\{1,\dots,\ell-1\}$ under $(q,r)\mapsto \ell^{k}(\ell q+r)$: divide $x/\ell^{k}$ by $\ell$ with remainder, the remainder being nonzero exactly when $\ell^{k+1}\nmid x$. Injectivity is uniqueness of division with remainder, and containment in the range is a size estimate. Summing over $k<b$ plus the singleton gives $\ell^{b}$.
\end{proof}

For instance $\ell=3$, $b=3$ gives the profile $(18,6,2,1)$, summing to $27$.

\begin{theorem}[Repunit form of the tie correction]\label{thm:repunit}
For $\ell\ge 2$ and $x=\ell^{b}$, $\;\sum_{m\in A_{b}^{(\ell)}}m^{3}=(\ell-1)^{3}\frac{x^{3}-1}{\ell^{3}-1}+1$.
\end{theorem}

\begin{proof}[Proof sketch]
Induction on $b$: prepending the class of size $(\ell-1)\ell^{b}$ adds $(\ell-1)^{3}\ell^{3b}$, and $\sum_{j<b}\ell^{3j}=\frac{x^{3}-1}{\ell^{3}-1}$ telescopes.
\end{proof}

\begin{theorem}[The $\ell$-adic ceiling]\label{thm:elladic}
For $\ell\ge 2$, $b\ge 1$, with $x=\ell^{b}$,
\[
\CC\bigl(A_{b}^{(\ell)}\bigr)\;=\;\frac{3\ell}{\ell^{2}+\ell+1}\left(1+\frac{1}{x(x+1)}\right).
\]
\end{theorem}

\begin{proof}[Proof sketch]
By Theorem~\ref{thm:repunit}, $V=x^{3}-x-\bigl[(\ell-1)^{3}\frac{x^{3}-1}{\ell^{3}-1}+1-x\bigr]=(x^{3}-1)\bigl(1-\frac{(\ell-1)^{3}}{\ell^{3}-1}\bigr)$. Since $\ell^{3}-1=(\ell-1)(\ell^{2}+\ell+1)$, the bracket equals $1-\frac{(\ell-1)^{2}}{\ell^{2}+\ell+1}=\frac{3\ell}{\ell^{2}+\ell+1}$. Divide by $x^{3}-x$ and cancel $x-1$.
\end{proof}

At $\ell=2$ the prefactor is $\frac{6}{7}$, recovering Theorem~\ref{thm:dyadic}. For fixed $\ell$ the ceiling is within $\ell^{-2b}$ of its limit, so bitlen stability is modulus-uniform.

\begin{theorem}[Strict antitonicity in the modulus]\label{thm:anti}
$L(\ell)=\frac{3\ell}{\ell^{2}+\ell+1}$ is strictly decreasing for $\ell\ge 2$, with $L(\ell)\to 0$.
\end{theorem}

\begin{proof}
For $2\le\ell<m$, cross-multiplication reduces $L(m)<L(\ell)$ to $0<(m-\ell)(\ell m-1)$.
\end{proof}

This refutes the natural conjecture that a finer valuation grading raises the ceiling. The mechanism is visible in the profile: the class $v=0$ holds a fraction $(\ell-1)/\ell$ of the sample, and since ties cost cubically that single dominant block outweighs the extra classes. Values: $L(2)=\frac{6}{7}=0.857143$, $L(3)=\frac{9}{13}=0.692308$, $L(4)=\frac{4}{7}=0.571429$, $L(5)=\frac{15}{31}=0.483871$.

\begin{theorem}[The recorded dial bounds the sampling modulus]\label{thm:modbound}
For every $\ell\ge 5$ and every $b\ge 1$, $\;\CC\bigl(A_{b}^{(\ell)}\bigr)<0.7192^{2}=0.5172\ldots$
\end{theorem}

\begin{proof}
For $\ell\ge 5$, $L(\ell)\le\frac{15}{31}$ by Theorem~\ref{thm:anti} and $x=\ell^{b}\ge 5$ gives $\frac{1}{x(x+1)}\le\frac{1}{30}$; hence $\CC\le\frac{15}{31}\cdot\frac{31}{30}=\frac12<0.5172$.
\end{proof}

\begin{theorem}[Sharpness]
For every $b\ge 1$ and $\ell\in\{2,3,4\}$, $\;\CC\bigl(A_{b}^{(\ell)}\bigr)>0.7192^{2}$, since $\CC\ge L(\ell)$ and $L(2),L(3),L(4)$ all exceed $0.5173$.
\end{theorem}

So the recorded number certifies $\ell\le 4$: a sharp arithmetic constraint on the sampling geometry deduced from a single measured correlation. Contrasting the two axes: moving the bit length from $48$ to $52$ moves every ceiling by less than $10^{-40}$, while moving the modulus from $2$ to $3$ moves the ceiling by $L(2)-L(3)=\frac{15}{91}>0.16$. The bit length is a nuisance parameter of the dial; the modulus is not.

\section{Algorithms}

Three primitives suffice to reproduce every number above, all in exact rational arithmetic.

\paragraph{A. Tie-ceiling evaluation.} Given $P=(m_{1},\dots,m_{r})$ with $n=\sum m_{i}$, return $1-\frac{\sum(m_{i}^{3}-m_{i})}{n^{3}-n}$. Cost $O(r)$ big-integer operations; for $P=A_{b}$ that is $O(b)$ multiplications of $O(b)$-bit numbers.

\paragraph{B. Ladder ceiling by closed form.} Given $(b,t)$ and a blindfold type, return the value from Theorem~\ref{thm:coarse}, \ref{thm:tip} or \ref{thm:bulk}; cost $O(1)$ rational operations. Correctness is checkable against primitive~A on the explicitly merged profile.

\paragraph{C. Bitlen-gap certification.} Given $b,c,t$, return the actual gap together with the certificate $3\cdot 8^{-b}+3\cdot 8^{-c}$ and verify the former does not exceed the latter. Cost $O(1)$, independent of $t$: the routine \emph{replaces} a bit-length sweep rather than performing one.

\begin{verbatim}
input : b, c (valuation-class counts), t (depth), kind in {coarse,tip,bulk}
output: (gap, bound, verdict)

p      <- 2^(-t)
g      <- coarse: (7/2)*p*(1-p) | tip: 1 - p^3 | bulk: (7/2)*p*(1-p) + p^3
h      <- if kind = bulk then -1 else 0
Xb, Xc <- 8^b, 8^c
Cb     <- (Xb*g + h)/(Xb - 1)
Cc     <- (Xc*g + h)/(Xc - 1)
gap    <- |Cb - Cc|
bound  <- 3/Xb + 3/Xc
return (gap, bound, gap <= bound)
\end{verbatim}

\section{Discussion}

\subsection{What was proved}

The empirical claim under test was modest --- six cells inside a band with a consistent advantage over a control. What the analysis delivers is a \emph{rigidity} statement: every ceiling of the dial's ladder is of the affine shape $(Xg+h)/(X-1)$ in the single quantity $X=8^{b}$, with a bitlen-free $g\in[0,1]$ and $|h|\le 1$. Bit length therefore acts through one scalar Möbius factor $1+\frac{1}{X-1}$. This explains at once why bitlen-stability holds, why it holds to accuracy $10^{-42}$ rather than to a few percent, and why a bit-length scan of this dial is informationally empty beyond $b\approx 5$: the scan measures noise, and further scanning cannot change that. Methodologically, this converts an open-ended validation programme into a closed one.

\subsection{The source of the rigidity}

The rigidity is a property of the tie profile, not of the response, the target, or the coefficient. Its source is the fixed-point identity $A_{b+1}=(2^{b})\frown A_{b}$: adding a bit prepends one step to the staircase instead of deforming it, so the cube sums form a geometric series and the ceiling converges geometrically. Section~\ref{sec:modulus} confirms this by exhibiting the $\ell$-adic family, self-similar for each fixed $\ell$, with the same $1/(x(x+1))$ correction and a modulus-dependent constant.

\subsection{Limitations}

\begin{itemize}
  \item \emph{Ceilings, not attainment.} All statements of \S\S\ref{sec:ladder}--\ref{sec:nocliff} are upper bounds, attained by explicitly constructed coarse responses; the recorded dial $0.7192$ sits well below the tip-blind ceiling $>0.99$ and below $\sqrt{6/7}=0.9258$. The bounds exclude scenarios rather than predicting the observed value.
  \item \emph{The band is an input.} $[0.60,0.85]$ is a deployment specification; what is proved is that the tie geometry cannot push the dial out of it and that every value inside it is attainable at every bit length.
  \item \emph{Two bit lengths.} The empirical component is a two-point comparison with three seeds each; it is the theory that extends the conclusion to all bit lengths.
  \item \emph{Non-tie size effects.} Rigidity concerns the tie structure only. Arithmetic phenomena that genuinely change with sample range lie outside its scope.
\end{itemize}

\subsection{Future directions}

\paragraph{Where the Möbius rigidity breaks.} The shape lemma needs the limit $g$ to be bitlen-free, an artefact of the tie profile being self-similar. For a non-self-similar profile --- the number of representations of $n$ as a sum of two squares, or a Pythagorean-leg-count statistic --- the limit $g$ should itself move with $b$, giving a genuine $1/b$ decline rather than an $8^{-b}$ one. Bitlen-stability is a \emph{fixed-point property of the tie profile under bit-extension}, not a property of the response; classifying profiles by their extension behaviour, with matching decline rates, is the natural next theorem.

\paragraph{From ceilings to attainment.} The gap between the recorded $0.7192$ and the tip-blind ceiling $>7/8$ shows the response class is badly under-determined. A rate--distortion style converse --- \emph{any response achieving $\rho\ge 0.7192$ must separate at least $k$ valuation classes} --- would turn the dial into a measurement of information content rather than a bounded-above score.

\paragraph{The modulus axis, pushed further.} Two follow-ups: mixed moduli, where the grading uses several primes at once and the profile is a product, so the tie sum should factor; and sharpening the exclusion $\ell\le 4$ by using the measured value rather than the band, which would separate $\ell=4$ from $\ell\in\{2,3\}$ once the response class is pinned down.

\section{Conclusion}

The dial reads $0.7192$ at $48$ bits and $0.7161$ at $52$ bits, and the temptation is to argue about whether the difference of $0.0036$ is decay. The structure of the problem removes the need to argue: the whole tie-geometric ladder --- coarse, tip-blind and bulk-blind ceilings at every depth --- moves by less than $10^{-42}$ between those sizes, because bit length enters only through $1+1/(8^{b}-1)$. The measured drift exceeds that budget by more than $10^{37}$, so it is noise; no cliff is possible, since the band lies strictly below the tie ceiling at every size; and even the pessimistic extrapolation keeps the instrument in band to $160$ bits. The advantage over a bare quadratic-residue count is structural, separated by the uniform cap $\rho^{2}<0.3829$ that any single-bit response at relation rate $1/8$ must obey. The rigidity is genuine rather than tautological: the neighbouring modulus axis moves the ceiling by more than $0.16$ in one step, and its closed form both refutes the intuition that finer grading helps and converts the recorded correlation into the hard arithmetic constraint $\ell\le 4$.

